/* ── REGIME DISPLAY UPDATER (immune to floor overwrite) ── */
function updateRegimeDisplay(d) {
  var el = document.getElementById('regimeDisplay_xyz');
  if (!el) return;
  var val = typeof d.regime === 'string' && isNaN(d.regime) ? d.regime : (d.adv_regime || 'NORMAL');
  var color = val === 'CAPITULATION' || val === 'CRISIS' ? 'var(--red)' : val === 'STRESS' || val === 'BEAR' ? 'var(--amber)' : 'var(--green)';
  el.textContent = val;
  el.style.color = color;
}
// Aggressive poll: fix regime display every 200ms to prevent floor overwrite
setInterval(function() {
  var el = document.getElementById('regimeDisplay_xyz');
  if (!el) return;
  var d = currentData || window.__EMBEDDED_DATA;
  if (!d) return;
  var val = typeof d.regime === 'string' && isNaN(d.regime) ? d.regime : (d.adv_regime || 'NORMAL');
  var txt = el.textContent;
  // If it contains a $ sign or a number with decimal, overwrite
  if (/^\$?[\d,]+\.?\d*$/.test(txt.trim())) {
    el.textContent = val;
    el.style.color = val === 'CAPITULATION' || val === 'CRISIS' ? 'var(--red)' : val === 'STRESS' || val === 'BEAR' ? 'var(--amber)' : 'var(--green)';
  }
}, 200);

/* ── PAPER SECTION TOGGLE ── */
let paperVisible = true;
function togglePaperSection() {
  paperVisible = !paperVisible;
  const p = document.getElementById('paperBody');
  const tHead = document.getElementById('paperToggleHead');
  const tFoot = document.getElementById('paperToggle');
  if (p) p.style.display = paperVisible ? 'block' : 'none';
  const arrow = paperVisible ? '▲' : '▼';
  if (tHead) {
    tHead.textContent = arrow;
    tHead.title = paperVisible ? 'Collapse card' : 'Expand card';
  }
  if (tFoot) {
    tFoot.textContent = arrow + (paperVisible ? ' Hide' : ' Show');
  }
}

/* ── SERVER PAPER TRADING TRACK RECORD ── */
async function fetchPaperTrackRecord() {
  try {
    const r = await fetch('paper_history.json?t=' + Date.now(), { cache: 'no-cache' });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const data = await r.json();
    const cur = data.current || {};
    const el = id => document.getElementById(id);
    if (el('paperEquity')) {
      el('paperEquity').textContent = '$' + fmtNum(cur.equity || 50000, 2);
      el('paperEquity').style.color = (cur.total_return || 0) >= 0 ? 'var(--green)' : 'var(--red)';
    }
    if (el('paperReturn')) {
      el('paperReturn').textContent = (cur.total_return_pct || 0).toFixed(2) + '%';
      el('paperReturn').style.color = (cur.total_return_pct || 0) >= 0 ? 'var(--green)' : 'var(--red)';
    }
    if (el('paperSharpe')) el('paperSharpe').textContent = (cur.sharpe || 0).toFixed(2);
    if (el('paperSharpe')) el('paperSharpe').style.color = cur.sharpe > 1.5 ? 'var(--green)' : cur.sharpe > 0.5 ? 'var(--amber)' : 'var(--red)';
    if (el('paperWinRate')) el('paperWinRate').textContent = (cur.win_rate_pct || 0).toFixed(0) + '%';
    if (el('paperWinRate')) el('paperWinRate').style.color = (cur.win_rate_pct || 0) > 60 ? 'var(--green)' : 'var(--amber)';
    if (el('paperDD')) el('paperDD').textContent = (cur.max_dd_pct || 0).toFixed(1) + '%';
    if (el('paperDD')) el('paperDD').style.color = (cur.max_dd_pct || 0) < 10 ? 'var(--green)' : (cur.max_dd_pct || 0) < 20 ? 'var(--amber)' : 'var(--red)';
    if (el('paperPnL')) {
      const pnl = cur.unrealized_pnl || 0;
      el('paperPnL').textContent = (pnl >= 0 ? '+' : '') + '$' + pnl.toFixed(2);
      el('paperPnL').style.color = pnl >= 0 ? 'var(--green)' : 'var(--red)';
    }
    if (el('paperTradeCount')) el('paperTradeCount').textContent = cur.total_trades || 0;

    // Track record text
    const days = data.daily ? data.daily.length : 0;
    let recordHtml = '<span style="color:var(--text-2)">Server-side paper trader</span>';
    if (data.daily && data.daily.length >= 1) {
      const first = data.daily[0];
      const last = data.daily[data.daily.length - 1];
      recordHtml += '<br><span style="color:var(--text-2)">' + days + ' day' + (days>1?'s':'') + ' tracked &middot; ';
      recordHtml += 'Start: $' + fmtNum(first.equity, 2) + ' &middot; ';
      recordHtml += 'Latest: $' + fmtNum(last.equity, 2) + '</span>';
    }
    if (el('paperTrackRecord')) el('paperTrackRecord').innerHTML = recordHtml;
    if (el('paperLastUpdate')) el('paperLastUpdate').textContent = new Date().toLocaleTimeString();
    return data;
  } catch (e) {
    const el = document.getElementById('paperTrackRecord');
    if (el) el.innerHTML = '<span style="color:var(--text-3)">Server track record not available yet</span>';
    return null;
  }
}

