/* ── PARTIAL UPDATE (BTC ticker — smooth, no DOM rebuild) ── */
function partialUpdate(btcData) {
  // Update BTC price
  const priceEl = document.getElementById('btcPriceKpi');
  if (priceEl && btcData.price != null) {
    priceEl.textContent = '$' + fmtNum(btcData.price);
    // Real-time trailing stop check on every BTC tick
    if (paperTrader && paperTrader.positions && paperTrader.positions.length > 0) {
      const tradesBefore = paperTrader.trades.length;
      paperTrader._checkTrailingStop(btcData.price);
      if (paperTrader.trades.length > tradesBefore) {
        const lastTrade = paperTrader.trades[paperTrader.trades.length - 1];
        if (lastTrade.reason && lastTrade.reason.startsWith('Trailing Stop')) {
          addPaperLog(`🔴 [TRAILING STOP] $${fmtNum(btcData.price,0)} — ${lastTrade.reason}`);
          updatePaperDisplay();
        }
      }
    }
  }

  // Update 24h change
  const chgEl = document.getElementById('btcChgKpi');
  if (chgEl && btcData.change_pct != null) {
    const chg = btcData.change_pct;
    chgEl.textContent = (chg > 0 ? '\u25B2' : chg < 0 ? '\u25BC' : '\u25CF') + ' ' + Math.abs(chg).toFixed(2) + '% 24h';
    chgEl.className = chg > 0 ? 'chg-p' : chg < 0 ? 'chg-n' : 'chg-z';
  }

  // Update last update timestamp
  const tsEl = document.getElementById('navLastUpdate');
  if (tsEl) {
    tsEl.textContent = new Date().toLocaleTimeString();
  }
}

/* ── SSE CONNECTION ── */
let sseSource = null;
let sseReconnectTimer = null;

function startSSE() {
  // Close existing connection if any
  if (sseSource) {
    sseSource.close();
    sseSource = null;
  }
  if (sseReconnectTimer) {
    clearTimeout(sseReconnectTimer);
    sseReconnectTimer = null;
  }

  try {
    sseSource = new EventSource('/events');

    sseSource.addEventListener('btc_ticker', function(e) {
      try {
        const data = JSON.parse(e.data);
        partialUpdate(data);
      } catch (err) {
        console.log('[SSE] btc_ticker parse error:', err);
      }
    });

    sseSource.addEventListener('sfc_update', function(e) {
      try {
        const data = JSON.parse(e.data);
        if (data.btc != null || data.sfc_effective != null) {
          // Merge BTC ticker data from btc_ticker event into sfc data
          // to avoid stale BTC in the full render
          if (currentData) {
            Object.assign(data, { btc: data.btc || currentData.btc });
          }
          currentData = data;
          render(data);
          startNewsSlide();
          // Restore config panel after SSE render
          if (currentUser && paperTrader) {
            loadConfigToForm(paperTrader.userConfig || {});
            updatePaperDisplay();
          }
        }
      } catch (err) {
        console.log('[SSE] sfc_update parse error:', err);
      }
    });

    sseSource.onerror = function() {
      console.log('[SSE] Connection lost — will retry');
      if (sseSource) {
        sseSource.close();
        sseSource = null;
      }
      // Reconnect after 5s
      sseReconnectTimer = setTimeout(startSSE, 5000);
    };
  } catch (e) {
    console.log('[SSE] Failed to create EventSource:', e);
    // Fallback: start polling after a delay
    sseReconnectTimer = setTimeout(startSSE, 10000);
  }
}

/* ── INITIAL DATA FETCH (via SSE snapshot) ── */
async function fetchInitialData() {
  try {
    const r = await fetch('/snapshot');
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return await r.json();
  } catch (e) {
    console.log('[Init] Snapshot fetch failed:', e);
    return null;
  }
}

/* ── FETCH (fallback polling — used only if SSE fails) ── */
async function fetchLiveData() {
  try {
    // Save actual scroll position before DOM rebuild
    const savedScrollY = window.scrollY;
    const r = await fetch('data.json?t=' + Date.now(), { cache: 'no-cache' });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const data = await r.json();
    currentData = data;
    window.__EMBEDDED_DATA = data;
    render(data);
    // Restore exact scroll position (not activeTab section)
    window.scrollTo({ top: savedScrollY, behavior: 'instant' });
    startNewsSlide();
    // Restore config panel values after render
    if (currentUser && paperTrader) {
      loadConfigToForm(paperTrader.userConfig || {});
      updatePaperDisplay();
    }
    return true;
  } catch (e) {
    console.log('Fetch failed:', e);
    return false;
  }
}

/* ── PAPER TRADING ENGINE (mirrors server paper_trader.py) ── */
const PAPER_INITIAL_CAPITAL = 50000;
const PAPER_MAX_POSITION_PCT = 0.25;

class PaperTrader {
  constructor(capital = PAPER_INITIAL_CAPITAL, state = null) {
    if (state) {
      // Load from server state
      this.capital = state.capital || capital;
      this.initial = state.initial_capital || capital;
      this.peakCapital = state.peak_capital || capital;
      this.positions = state.positions || [];
      this.trades = state.trades || [];
      this.equityHistory = state.equity_history || [];
      this.dailySnapshots = state.daily_snapshots || {};
      this._initialized = true;
      this._serverStateLoaded = true;
      this._serverStateLogged = false;
    } else {
      this.capital = capital;
      this.initial = capital;
      this.peakCapital = capital;
      this.positions = [];        // open positions [{type,entry_price,size,entry_date,reason,sfc_at_entry,confidence_at_entry}]
      this.trades = [];            // all trades [{id,type,date,price,size,...}]
      this.equityHistory = [];     // [{ts,btc,equity,capital,unrealized}]
      this.dailySnapshots = {};    // date -> {equity,return_pct,sharpe,win_rate,max_dd_pct,total_trades,open_positions,status}
      this._initialized = false;
      this._serverStateLoaded = false;
    }
    this.status = this.positions.length > 0 ? 'IN_MARKET' : 'IDLE';
    this._lastSignalTs = 0;
    this._unrealized = 0;
    this._trailingStopTriggered = false;
  }

  evaluateSignal(d) {
    const sfc = (d.sfc_effective || 0) / 100;
    const conf = d.composite_confidence || 0.3;
    const kelly = d.kelly_fraction || 0;
    const fng = d.fng || 50;
    const cascade = d.cascade_risk || 0;
    const regime = d.regime || 'NORMAL';
    const zone = d.zone || 'NORMAL';
    const btc = d.btc || 0;
    const signalType = d.signal_type || 'CALM';

    const isExtremeFear = fng < 15;
    const hasCascade = cascade > 0.5;

    let action, reason;
    if (kelly <= 0) {
      action = 'CASH';
      reason = 'No edge';
      if (d.kelly_override_reason === 'TRANSITION_RISK_OVER_60') reason = 'Transition Risk >60% · Forced CASH';
      else if (isExtremeFear) reason = `FNG ${fng} · Extreme Fear`;
      else if (hasCascade) reason = `Cascade Risk ${(cascade*100).toFixed(0)}%`;
    } else if (sfc < 0.25 && conf > 0.15) {
      action = 'BUY';
      reason = `SFC ${(sfc*100).toFixed(0)}% · Conf ${(conf*100).toFixed(0)}%`;
    } else if (sfc >= 0.45) {
      action = 'CASH';
      reason = `SFC ${(sfc*100).toFixed(0)}% · Stress too high`;
    } else {
      action = 'HOLD';
      reason = `SFC ${(sfc*100).toFixed(0)}% · Neutral zone`;
    }

    let sizePct = 0;
    if (action === 'BUY') {
      sizePct = Math.min(kelly, PAPER_MAX_POSITION_PCT);
      sizePct *= Math.min(conf * 2, 1.0);
    }

    const size = Math.round(this.capital * sizePct * 100) / 100;

    return {
      action,
      size: action === 'BUY' ? size : 0,
      reason,
      btc_price: btc,
      sfc_pct: Math.round(sfc * 1000) / 10,
      confidence: Math.round(conf * 100),
      kelly_pct: Math.round(kelly * 1000) / 10,
      regime,
      zone,
      signal_type: signalType,
    };
  }

  execute(decision) {
    const price = decision.btc_price || 0;
    if (!price || price <= 0) return;

    // Get user's TP/SL config
    const tpPct = (this.userConfig?.take_profit_pct || 0) / 100;
    const slPct = (this.userConfig?.stop_loss_pct || 0) / 100;

    // Check TAKE PROFIT for each position
    if (tpPct > 0 && this.positions.length > 0) {
      const tpTarget = this.positions[0].entry_price * (1 + tpPct);
      if (price >= tpTarget) {
        this._closeAllPositions(price, 'Take Profit ' + (tpPct * 100).toFixed(0) + '% · Hit $' + Math.round(price));
      }
    }

    // Check STOP LOSS for each position
    if (slPct > 0 && this.positions.length > 0) {
      const slTarget = this.positions[0].entry_price * (1 - slPct);
      if (price <= slTarget) {
        this._closeAllPositions(price, 'Stop Loss ' + (slPct * 100).toFixed(0) + '% · Hit $' + Math.round(price));
      }
    }

    // Close positions if signal says CASH and we have positions
    if (decision.action === 'CASH' && this.positions.length > 0) {
      this._closeAllPositions(price, 'Signal CASH');
    }

    // Open new position if signal says BUY and we're flat
    if (decision.action === 'BUY' && this.positions.length === 0 && decision.size >= 10) {
      this._openPosition(decision.size, price, decision);
    }

    // Update PnL for reporting
    this._updatePnL(price);
    this._updatePeak();
    // Trailing stop check — uses user's configured trailing stop %
    this._checkTrailingStop(price);
    this._dailySnapshot();
  }

  _openPosition(size, price, decision) {
    this.positions.push({
      type: 'LONG',
      entry_price: price,
      highest_price: price,
      size: size,
      entry_date: new Date().toISOString(),
      reason: decision.reason || '',
      sfc_at_entry: decision.sfc_pct,
      confidence_at_entry: decision.confidence,
    });
    this.capital -= size;
    this.trades.push({
      id: this.trades.length + 1,
      type: 'OPEN',
      date: new Date().toISOString(),
      price: price,
      size: size,
      reason: decision.reason || '',
    });
    this.status = 'IN_MARKET';
  }

  _closeAllPositions(price, reason) {
    for (const pos of this.positions) {
      const pnl = (price - pos.entry_price) / pos.entry_price * pos.size;
      this.capital += pos.size + pnl;
      this.trades.push({
        id: this.trades.length + 1,
        type: 'CLOSE',
        date: new Date().toISOString(),
        price: price,
        size: pos.size,
        pnl: Math.round(pnl * 100) / 100,
        pnl_pct: Math.round((price - pos.entry_price) / pos.entry_price * 10000) / 100,
        reason: reason,
      });
    }
    this.positions = [];
    this.status = 'IDLE';
  }

  _checkTrailingStop(price) {
    const TRAILING_PCT = (this.userConfig?.trailing_stop_pct || 15) / 100; // From user config, default 15%
    const toClose = [];
    for (const pos of this.positions) {
      // Update highest price seen
      if (price > pos.highest_price) {
        pos.highest_price = price;
      }
      // Check if price dropped from peak
      const dropPct = (pos.highest_price - price) / pos.highest_price;
      if (dropPct >= TRAILING_PCT) {
        toClose.push(pos);
      }
    }
    if (toClose.length > 0) {
      this._trailingStopTriggered = true;
      this._closeAllPositions(price, `Trailing Stop ${(TRAILING_PCT*100).toFixed(0)}% · Drop ${Math.round(toClose[0].highest_price)}→${Math.round(price)}`);
    }
  }

  _updatePnL(price) {
    let unrealized = 0;
    for (const pos of this.positions) {
      if (pos.type === 'LONG') {
        unrealized += (price - pos.entry_price) / pos.entry_price * pos.size;
      }
    }
    this._unrealized = unrealized;
    const equity = this.capital + this.positions.reduce((s,p) => s + p.size, 0) + unrealized;
    this.equityHistory.push({
      ts: new Date().toISOString(),
      btc: price,
      equity: Math.round(equity * 100) / 100,
      capital: Math.round(this.capital * 100) / 100,
      unrealized: Math.round(unrealized * 100) / 100,
    });
    return equity;
  }

  // Real-time PnL update — no new history entry, just updates the last one
  _updatePnLRealtime(price) {
    if (this.positions.length === 0) return this.capital;
    let unrealized = 0;
    for (const pos of this.positions) {
      if (pos.type === 'LONG') {
        unrealized += (price - pos.entry_price) / pos.entry_price * pos.size;
      }
    }
    this._unrealized = unrealized;
    const equity = this.capital + this.positions.reduce((s,p) => s + p.size, 0) + unrealized;
    const rounded = Math.round(equity * 100) / 100;
    // Update the last history entry in-place
    if (this.equityHistory.length > 0) {
      const last = this.equityHistory[this.equityHistory.length - 1];
      last.btc = price;
      last.equity = rounded;
      last.unrealized = Math.round(unrealized * 100) / 100;
    }
    return equity;
  }

  _updatePeak() {
    const equity = this.getEquity();
    if (equity > this.peakCapital) this.peakCapital = equity;
  }

  _dailySnapshot() {
    const today = new Date().toISOString().slice(0, 10);
    const perf = this.getPerformance();
    this.dailySnapshots[today] = {
      date: today,
      equity: Math.round(perf.equity * 100) / 100,
      return_pct: Math.round(perf.total_return * 10000) / 100,
      sharpe: Math.round(perf.sharpe * 100) / 100,
      win_rate: Math.round(perf.win_rate * 10000) / 10000,
      max_dd_pct: Math.round(perf.max_dd * 10000) / 100,
      total_trades: perf.total_trades,
      open_positions: this.positions.length,
      status: this.positions.length > 0 ? 'IN_MARKET' : 'CASH',
    };
  }

  getEquity() {
    if (this.positions.length === 0) return this.capital;
    return this.equityHistory.length > 0 ? this.equityHistory[this.equityHistory.length - 1].equity : this.capital;
  }

  getPerformance() {
    const equity = this.getEquity();
    const totalReturn = (equity - this.initial) / this.initial;

    const closed = this.trades.filter(t => t.pnl !== undefined);
    const wins = closed.filter(t => t.pnl > 0);
    const winRate = closed.length > 0 ? wins.length / closed.length : 0;

    // Sharpe from equity history — only meaningful with 2+ entries
    const rets = [];
    if (this.equityHistory.length >= 2) {
      for (let i = 1; i < this.equityHistory.length; i++) {
        const prev = this.equityHistory[i - 1].equity;
        const cur = this.equityHistory[i].equity;
        if (prev > 0) rets.push((cur - prev) / prev);
      }
    }
    const mean = rets.length > 0 ? rets.reduce((a, b) => a + b, 0) / rets.length : 0;
    const std = rets.length > 1 ? Math.sqrt(rets.map(r => (r - mean) ** 2).reduce((a, b) => a + b, 0) / rets.length) : 1;
    const sharpe = std > 0 && rets.length > 1 ? mean / std * Math.sqrt(252) : 0;

    // Max drawdown
    let mdd = 0;
    let peak = this.initial;
    for (const h of this.equityHistory) {
      const eq = h.equity;
      if (eq > peak) peak = eq;
      const dd = peak > 0 ? (peak - eq) / peak : 0;
      if (dd > mdd) mdd = dd;
    }

    return {
      initial_capital: this.initial,
      capital: Math.round(this.capital * 100) / 100,
      equity: Math.round(equity * 100) / 100,
      peak_equity: Math.round(this.peakCapital * 100) / 100,
      total_return: Math.round(totalReturn * 10000) / 10000,
      total_return_pct: Math.round(totalReturn * 10000) / 100,
      sharpe: Math.round(sharpe * 100) / 100,
      win_rate: Math.round(winRate * 10000) / 10000,
      win_rate_pct: Math.round(winRate * 10000) / 100,
      max_dd: Math.round(mdd * 10000) / 10000,
      max_dd_pct: Math.round(mdd * 10000) / 100,
      total_trades: this.trades.length,
      closed_trades: closed.length,
      open_positions: this.positions.length,
      unrealized_pnl: Math.round((this._unrealized || 0) * 100) / 100,
      status: this.positions.length > 0 ? 'IN_MARKET' : 'CASH',
    };
  }
}

let paperTrader = null;

async function initPaperTrading() {
  // Multi-user mode: load from KV
  if (currentUser) {
    try {
      const res = await fetch('/user/' + encodeURIComponent(currentUser) + '/state', { cache: 'no-cache' });
      if (res.ok) {
        const kvState = await res.json();
        // Create PaperTrader FROM KV state — preserves user's own trades/positions
        const kvCapital = kvState.capital || PAPER_INITIAL_CAPITAL;
        paperTrader = new PaperTrader(kvCapital, {
          capital: kvState.capital,
          peak_capital: kvState.peak_capital,
          positions: kvState.positions,
          trades: kvState.trades,
          equity_history: kvState.equity_history,
          daily_snapshots: kvState.daily_snapshots,
        });
        paperTrader.userConfig = kvState.config || {};

        // Validate equity_history — if first entry doesn't match capital, clear it
        // (legacy data from before multi-user fix, see Q8 implementation)
        if (paperTrader.equityHistory.length > 0) {
          const firstEq = paperTrader.equityHistory[0].equity;
          if (Math.abs(firstEq - kvCapital) > 1) {
            paperTrader.equityHistory = [];
            paperTrader.dailySnapshots = {};
          }
        }

        // Patch for auto-save
        const origExecute = paperTrader.execute;
        const origCloseAll = paperTrader.closeAll;
        paperTrader.execute = function(decision, price) {
          const result = origExecute.call(this, decision, price);
          saveUserState().catch(() => {});
          return result;
        };
        paperTrader.closeAll = function(price, reason) {
          const result = origCloseAll.call(this, price, reason);
          saveUserState().catch(() => {});
          return result;
        };

        loadConfigToForm(paperTrader.userConfig || {});
        addPaperLog('👤 Multi-user: loaded state for ' + currentUser);
        return;
      }
    } catch (e) {
      console.warn('KV load failed, falling back', e);
    }
  }

  // Fallback: server-side paper_trades.json (single-user VPS mode)
  try {
    const r = await fetch('paper_trades.json?t=' + Date.now(), { cache: 'no-cache' });
    if (r.ok) {
      const state = await r.json();
      paperTrader = new PaperTrader(PAPER_INITIAL_CAPITAL, state);
      return;
    }
  } catch (e) {}
  paperTrader = new PaperTrader(PAPER_INITIAL_CAPITAL);
}

function processSignalFromSFC(d) {
  if (!paperTrader) return;

  // Restore paper log if render() wiped it — check if only placeholder remains
  const _log = document.getElementById('paperLog');
  if (_log && _log.children.length <= 1 && paperTrader._initialized) {
    _log.innerHTML = '';
    // Allow server state logging to re-run if it was already logged
    if (paperTrader._serverStateLoaded) {
      paperTrader._serverStateLogged = false;
    } else {
      addPaperLog('🟢 Paper trading initialized with $50,000 capital');
      addPaperLog('⏳ Waiting for first trade signal from SFC...');
    }
  }

  // Log server state on first processSignalFromSFC after server-load
  if (paperTrader._serverStateLoaded && !paperTrader._serverStateLogged) {
    paperTrader._serverStateLogged = true;
    const l = document.getElementById('paperLog');
    if (l) {
      l.innerHTML = '';
      addPaperLog('🟢 Paper trading — loaded server state');
      if (paperTrader.positions.length > 0) {
        const p = paperTrader.positions[0];
        addPaperLog(`🟢 [OPEN] LONG $${fmtNum(p.size,2)} at $${fmtNum(p.entry_price,2)} — ${p.reason}`);
      }
      const dayCount = Object.keys(paperTrader.dailySnapshots).length;
      addPaperLog(`📊 Day ${dayCount || 1} tracked · Equity: $${fmtNum(paperTrader.getEquity(), 2)}`);
    }
    updatePaperDisplay();
  }

  // First-call init: seed equityHistory so subsequent calls work
  if (!paperTrader._initialized) {
    paperTrader._initialized = true;
    paperTrader.equityHistory.push({
      ts: new Date().toISOString(),
      btc: d.btc || 0,
      equity: paperTrader.capital,
      capital: paperTrader.capital,
      unrealized: 0,
    });
    updatePaperDisplay();
    addPaperLog('🟢 Paper trading initialized with $50,000 capital');
    addPaperLog('⏳ Waiting for first trade signal from SFC...');
    return;
  }

  // 5s debounce — avoid double-processing when BTC+SFC arrive near-simultaneously
  const now = Date.now();
  if (now - paperTrader._lastSignalTs < 5000) return;
  paperTrader._lastSignalTs = now;

  // Evaluate signal (mirrors paper_trader.py evaluate_signal)
  const decision = paperTrader.evaluateSignal(d);

  // Execute trade decision (mirrors paper_trader.py execute)
  const tradesBefore = paperTrader.trades.length;
  paperTrader.execute(decision);

  // Log any trades that happened
  if (paperTrader.trades.length > tradesBefore) {
    const lastTrade = paperTrader.trades[paperTrader.trades.length - 1];
    if (lastTrade.type === 'OPEN') {
      addPaperLog(`🟢 [OPEN] LONG $${fmtNum(decision.size,0)} at $${fmtNum(decision.btc_price,0)} — ${decision.reason}`);
    } else if (lastTrade.type === 'CLOSE') {
      if (lastTrade.reason && lastTrade.reason.startsWith('Trailing Stop')) {
        addPaperLog(`🔴 [TRAILING STOP] $${fmtNum(decision.btc_price,0)} — ${lastTrade.reason}`);
      } else {
        addPaperLog(`🔴 [CLOSE] All at $${fmtNum(decision.btc_price,0)} — ${decision.reason}`);
      }
    }
    // Auto-save to KV after any trade
    if (currentUser) saveUserState().catch(() => {});
  } else if (decision.action === 'HOLD' && paperTrader.positions.length === 0 && Math.random() < 0.05) {
    addPaperLog(`👀 Watching — ${decision.reason}`);
  }

  updatePaperDisplay();
}

function updatePaperDisplay(perf) {
  if (!paperTrader) return;
  if (!perf) perf = paperTrader.getPerformance();
  const el = id => document.getElementById(id);
  if (!el('paperEquity')) return;

  el('paperEquity').textContent = '$' + fmtNum(perf.equity, 2);
  el('paperEquity').style.color = perf.total_return >= 0 ? 'var(--green)' : 'var(--red)';
  el('paperReturn').textContent = perf.total_return_pct.toFixed(2) + '%';
  el('paperReturn').style.color = perf.total_return >= 0 ? 'var(--green)' : 'var(--red)';
  el('paperSharpe').textContent = perf.sharpe.toFixed(2);
  el('paperSharpe').style.color = perf.sharpe > 1.5 ? 'var(--green)' : perf.sharpe > 0.5 ? 'var(--amber)' : 'var(--red)';
  el('paperWinRate').textContent = perf.win_rate_pct.toFixed(0) + '%';
  el('paperWinRate').style.color = perf.win_rate_pct > 60 ? 'var(--green)' : 'var(--amber)';
  el('paperDD').textContent = perf.max_dd_pct.toFixed(1) + '%';
  el('paperDD').style.color = perf.max_dd_pct < 10 ? 'var(--green)' : perf.max_dd_pct < 20 ? 'var(--amber)' : 'var(--red)';
  if (el('paperPnL')) {
    const pnl = perf.unrealized_pnl || 0;
    el('paperPnL').textContent = (pnl >= 0 ? '+' : '') + '$' + pnl.toFixed(2);
    el('paperPnL').style.color = pnl >= 0 ? 'var(--green)' : 'var(--red)';
  }
  el('paperTradeCount').textContent = perf.total_trades;

  const ps = document.getElementById('paperStatus');
  if (ps) ps.textContent = perf.open_positions > 0 ? '● IN MARKET' : '● CASH';
  if (el('paperLastUpdate')) el('paperLastUpdate').textContent = new Date().toLocaleTimeString();

  // Track record text from server-backed state
  const dailyKeys = Object.keys(paperTrader.dailySnapshots).sort();
  let recordHtml = '<span style="color:var(--text-2)">Server-backed paper trader</span>';
  if (dailyKeys.length >= 1) {
    const first = paperTrader.dailySnapshots[dailyKeys[0]];
    const last = paperTrader.dailySnapshots[dailyKeys[dailyKeys.length - 1]];
    recordHtml += '<br><span style="color:var(--text-2)">' + dailyKeys.length + ' day' + (dailyKeys.length !== 1 ? 's' : '') + ' tracked &middot; ';
    recordHtml += 'Start: $' + fmtNum(first.equity, 2) + ' &middot; ';
    recordHtml += 'Latest: $' + fmtNum(last.equity, 2) + '</span>';
  } else if (paperTrader.equityHistory.length > 0) {
    const first = paperTrader.equityHistory[0];
    const last = paperTrader.equityHistory[paperTrader.equityHistory.length - 1];
    recordHtml += '<br><span style="color:var(--text-2)">' + paperTrader.equityHistory.length + ' tick' + (paperTrader.equityHistory.length !== 1 ? 's' : '') + ' tracked &middot; ';
    recordHtml += 'Start: $' + fmtNum(first.equity, 2) + ' &middot; ';
    recordHtml += 'Latest: $' + fmtNum(last.equity, 2) + '</span>';
  } else {
    recordHtml += '<br><span style="color:var(--text-2)">Initialized &middot; Capital: $' + fmtNum(paperTrader.capital, 2) + '</span>';
  }
  if (el('paperTrackRecord')) el('paperTrackRecord').innerHTML = recordHtml;
}

function addPaperLog(msg) {
  const log = document.getElementById('paperLog');
  if (!log) return;
  const div = document.createElement('div');
  div.textContent = msg;
  log.appendChild(div);
  log.scrollTop = log.scrollHeight;
  while (log.children.length > 100) log.removeChild(log.firstChild);
}

function resetPaperTrading() {
  paperTrader = new PaperTrader(PAPER_INITIAL_CAPITAL);
  const log = document.getElementById('paperLog');
  if (log) log.innerHTML = '<div>🟢 Paper trading reset to $' + PAPER_INITIAL_CAPITAL.toLocaleString() + ' capital</div>';
  updatePaperDisplay();
  // Reset KV state for multi-user
  if (currentUser) {
    paperTrader.userConfig = {};
    saveUserState().catch(() => {});
    addPaperLog('💾 KV state reset saved');
  }
}

function exportPaperTrades() {
  if (!paperTrader || paperTrader.trades.length === 0) { addPaperLog('⚠ No trades to export'); return; }
  const blob = new Blob([JSON.stringify(paperTrader.trades, null, 2)], {type: 'application/json'});
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url;
  a.download = 'sfc_paper_trades_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(url);
  addPaperLog('📥 Exported ' + paperTrader.trades.length + ' trades');
}

function manualBuy() {
  if (!paperTrader) { addPaperLog('⚠ Paper trader not initialized'); return; }
  if (paperTrader.positions.length > 0) { addPaperLog('⚠ Already have an open position. Close it first or wait.'); return; }

  const price = currentData?.btc;
  if (!price || price <= 0) { addPaperLog('⚠ No BTC price available'); return; }

  // Get buy amount: user input or from config's max_allocation_pct
  const amountInput = document.getElementById('manualBuyAmount');
  let size = 0;
  if (amountInput?.value && parseFloat(amountInput.value) > 0) {
    size = parseFloat(amountInput.value);
  } else {
    const allocPct = (paperTrader.userConfig?.max_allocation_pct || 25) / 100;
    size = Math.round(paperTrader.capital * allocPct * 100) / 100;
  }

  // Cap at available capital
  size = Math.min(size, paperTrader.capital);
  if (size < 10) { addPaperLog('⚠ Insufficient capital (min $10)'); return; }

  const decision = {
    reason: 'Manual Buy',
    btc_price: price,
    sfc_pct: currentData?.sfc_effective || 0,
    confidence: currentData?.composite_confidence || 0,
  };

  paperTrader._openPosition(size, price, decision);
  paperTrader._updatePnL(price);
  paperTrader._dailySnapshot();

  addPaperLog(`🟢 [MANUAL BUY] LONG $${fmtNum(size,0)} at $${fmtNum(price,0)}`);
  updatePaperDisplay();

  // Clear the input
  if (amountInput) amountInput.value = '';

  // Save to KV
  if (currentUser) saveUserState().catch(() => {});
}

function manualCloseAll() {
  if (!paperTrader) { addPaperLog('⚠ Paper trader not initialized'); return; }
  if (paperTrader.positions.length === 0) { addPaperLog('⚠ No open positions to close'); return; }

  const price = currentData?.btc;
  if (!price || price <= 0) { addPaperLog('⚠ No BTC price available'); return; }

  paperTrader._closeAllPositions(price, 'Manual Close');
  paperTrader._updatePnL(price);
  paperTrader._dailySnapshot();

  addPaperLog(`🔴 [MANUAL CLOSE] All at $${fmtNum(price,0)}`);
  updatePaperDisplay();

  // Save to KV
  if (currentUser) saveUserState().catch(() => {});
}

/* ── INIT ── */
loadHistory();

// Load initial data from SSE snapshot — full render ONCE
let _sseAvailable = false;

async function bootSFC() {
  // PRIORITY 1: Try /snapshot for SSE connection (fastest — local server)
  let initial = null;
  try {
    const r = await fetch('/snapshot', { signal: AbortSignal.timeout(5000) });
    if (r.ok) initial = await r.json();
  } catch (e) { /* snapshot not available */ }

  if (initial && (initial.sfc || initial.btc)) {
    _sseAvailable = true;
    const data = initial.sfc || initial;
    currentData = data;
    render(data);
  } else {
    // No SSE server — fetch data.json directly (10-15KB, fast)
    await fetchLiveData();
  }

  // Now init paper trader in background
  await initPaperTrading();

  // Ensure config panel visible and values set after any render path
  setTimeout(function() {
    if (currentUser && paperTrader) {
      loadConfigToForm(paperTrader.userConfig || {});
      updatePaperDisplay();
    }
  }, 200);
  setTimeout(startNewsSlide, 100);
  setTimeout(restoreScrollPos, 200);
  // Start SSE only if server was detected (/snapshot responded)
  if (_sseAvailable) {
    startSSE();
  } else {
    // No SSE server — fall back to polling data.json every 30s
    setInterval(fetchLiveData, 30000);
  }
}
bootSFC();

// SSE handles real-time updates when available.
// On static (GitHub Pages / Workers), polling data.json every 30s is used instead.

// ── COLLAPSIBLE CARDS — expand/collapse below-fold sections
function toggleCollapseCard(el) {
  const card = el.closest('.card') || el.parentElement.closest('.card');
  if (!card) return;
  card.classList.toggle('card-collapsed');
  const arrow = card.querySelector('.collapse-arrow');
  if (arrow) arrow.textContent = card.classList.contains('card-collapsed') ? '▶' : '▼';
}

// ── LAZY LOADING ── Cards below fold render only when visible
function initLazyCards() {
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const el = entry.target;
          el.style.opacity = '1';
          el.style.transform = 'translateY(0)';
          observer.unobserve(el);
        }
      });
    }, { rootMargin: '200px' }); // start loading 200px before visible
    
    document.querySelectorAll('[data-lazy]').forEach(el => {
      el.style.opacity = '0';
      el.style.transform = 'translateY(20px)';
      el.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
      observer.observe(el);
    });
  }
}
// Run lazy observer after initial render (and after each re-render)
const origRender = render;
render = function(d) {
  origRender(d);
  // Delay observer until DOM is painted
  setTimeout(initLazyCards, 100);
};

// ── Donation: copy wallet address ──
function copyDonateAddress() {
  var addressEl = document.getElementById('donateAddress');
  var btn = document.getElementById('donateCopyBtn');
  if (!addressEl || !btn) return;
  var address = addressEl.textContent.trim();
  function showCopied() {
    btn.textContent = 'COPIED';
    btn.classList.add('copied');
    setTimeout(function() { btn.textContent = 'COPY'; btn.classList.remove('copied'); }, 1500);
  }
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(address).then(showCopied).catch(function() {
      var ta = document.createElement('textarea');
      ta.value = address; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); } catch (e) { console.error(e); }
      document.body.removeChild(ta); showCopied();
    });
  } else {
    var ta = document.createElement('textarea');
    ta.value = address; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch (e) { console.error(e); }
    document.body.removeChild(ta); showCopied();
  }
}

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('sw.js').catch(e => console.log('SW failed:', e));
  // When a new SW takes over, force a reload to pick up fresh index.html —
  // otherwise the page is stuck on the old cached HTML until next manual refresh.
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (navigator.serviceWorker.controller) {
      console.log('[SW] New controller — reloading');
      window.location.reload();
    }
  });
}
